@once<script>
function workLocationsPage(){const storeUrl=@js(route('hris.configuration.work-locations.store',['organization'=>$organization->slug]));const blank=()=>({mode:'create',action:storeUrl,name:'',type:'office',branch_id:'',address:'',latitude:'',longitude:'',radius_meters:50,geofence_enabled:true,is_active:true,notes:''});return{modal:false,assignModal:false,form:blank(),assignment:{action:'',name:'',employee_ids:[]},openCreate(){this.form=blank();this.modal=true},openEdit(d){this.form={...blank(),...d,mode:'edit'};this.modal=true},openAssign(d){this.assignment=d;this.assignModal=true},useCurrentLocation(){if(!navigator.geolocation)return;navigator.geolocation.getCurrentPosition(p=>{this.form.latitude=p.coords.latitude.toFixed(7);this.form.longitude=p.coords.longitude.toFixed(7)})}}}
</script>@endonce
